example_item.example_item_data:
% HRV d'un enregistrement simule, avec le LF/HF plante retrouve.
recording = ecglab.simulate('Seconds', 300, 'HeartRateStd', 5, 'Seed', 1);
hrv = ecglab.hrv(recording);
ratio = hrv.frequency.lfhf

% HRV a partir d'une simple liste d'intervalles RR en millisecondes, avec
% l'estimateur autoregressif et sans regle ectopique.
rr = 800 + 40 * randn(512, 1);
hrv = ecglab.hrv(rr, 'Unit', 'ms', 'Method', 'ar', 'Ectopic', 'none');
hrv.time.sdnn
